  "M 350 240 L 300 300 L 330 330", // L arm
  "M 350 240 L 390 310 L 460 250", // R arm
  "M 350 380 L 280 500 L 310 510", // L leg
  "M 350 380 L 380 500 L 420 510", // R leg
  "M 440 250 L 480 250", // Handle
