const doodle2StrokesBase: StrokeDef[] = [
  // House 1 (Left)
  "M 100 400 L 100 250 L 150 200 L 200 250 L 200 400 Z",
  "M 80 250 L 220 250",
  "M 130 400 L 130 330 L 170 330 L 170 400",
  "M 120 280 L 140 280 L 140 300 L 120 300 Z",
  "M 160 280 L 180 280 L 180 300 L 160 300 Z",
  // House 2 (Right)
  "M 700 400 L 700 250 L 800 200 L 900 250 L 900 400 Z",
  "M 680 250 L 920 250",
  "M 770 400 L 770 330 L 830 330 L 830 400",
  "M 740 280 L 760 280 L 760 300 L 740 300 Z",
  "M 840 280 L 860 280 L 860 300 L 840 300 Z",
  // Street
  "M 400 400 L 300 600",
  "M 600 400 L 700 600",
  "M 500 420 L 500 450",
  "M 500 490 L 500 530",
  "M 500 570 L 500 600",
  // Guy Walking (walking away in perspective)
  "M 500 200 A 30 30 0 0 1 500 260 A 30 30 0 0 1 500 200",
  "M 500 260 L 500 400",
  "M 500 300 L 460 350",
  "M 500 300 L 540 350",
  "M 500 400 L 480 450 L 480 500 L 460 500",
  "M 500 400 L 520 500 L 540 500",
  // Sign "TOWNSVILLE" (Scaled up by 1.5x)
  "M 290 550 L 290 325",
  { d: "M 155 250 L 425 250 L 425 325 L 155 325 Z", fill: true },
  "M 162.5 272.5 L 180.5 272.5 M 171.5 272.5 L 171.5 310", // T
  "M 189.5 290.5 A 9 18 0 0 1 207.5 290.5 A 9 18 0 0 1 189.5 290.5", // O
  "M 216.5 272.5 L 221 310 L 225.5 287.5 L 230 310 L 234.5 272.5", // W
  "M 243.5 310 L 243.5 272.5 L 261.5 310 L 261.5 272.5", // N
  "M 288.5 272.5 L 270.5 272.5 L 270.5 290.5 L 288.5 290.5 L 288.5 310 L 270.5 310", // S
  "M 297.5 272.5 L 306.5 310 L 315.5 272.5", // V
  "M 327.5 272.5 L 327.5 310", // I
  "M 342.5 272.5 L 342.5 310 L 360.5 310", // L
  "M 369.5 272.5 L 369.5 310 L 387.5 310", // L
  "M 414.5 272.5 L 396.5 272.5 L 396.5 310 L 414.5 310 M 396.5 290.5 L 410 290.5", // E
];

const HandwritingDoodle: React.FC<HandwritingDoodleProps> = ({
  backgroundColor = "#9df55a",
  transparentBackground = false,
  durationInSeconds = 16,
  text = "Jim Thompson went to the supermarket",
  text2 = "I live in my neighbourhood called Townsville",
  textColor = "#101010",
  highlightWords = ["Jim Thompson", "Townsville"],
  highlightColor = "#00ad77",
  paperColor = "#fdfdfd",
  lineColor = "#e0e0e0",
  strokeColor = "#101010",
  strokeWidth = 4,
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const bgColor = transparentBackground
    ? `${backgroundColor}00`
    : backgroundColor;

  // Layout calculations
  const paperWidth = width * 0.6;
  const paperHeight = height * 0.7;
  const paperLeft = (width - paperWidth) / 2;
  const paperTop = (height - paperHeight) / 2;

  // Timing helper function
  const f = useMemo(() => {
    return (percent: number) => Math.round(fps * durationInSeconds * percent);
  }, [fps, durationInSeconds]);

  // --- Animation Timings ---
  const paperScale = spring({
    frame,
    fps,
    config: { damping: 12 },
  });
  
  const paperRotate = interpolate(frame, [0, Math.max(0.001, f(0.1))], [-5, -1], {
    extrapolateRight: "clamp",
  });

  // Lines drawing
  const numLines = 11;
  const lineSpacing = paperHeight / (numLines + 1);
  const linesStartPercent = 0.025;
  const linesDurationPercent = 0.075;
  const timePerLine = linesDurationPercent / numLines;

  const paperLines = useMemo(() => {
    return Array.from({ length: numLines }).map((_, i) => {
      const y = (i + 1) * lineSpacing;
      const start = f(linesStartPercent + i * timePerLine);
      const dur = f(timePerLine * 2); // overlap
      return {
        d: `M ${paperWidth * 0.05} ${y} L ${paperWidth * 0.95} ${y}`,
        start,
        dur,
      };
    });
  }, [numLines, lineSpacing, paperWidth, f, timePerLine, linesStartPercent]);

  // Word Data Factory Function
  const createWordData = (
    textStr: string,
    startPercent: number,
    durPercent: number,
    eraseStartPercent?: number,
    eraseDurPercent?: number
  ) => {
    const parts = textStr.split(/(\s+)/).filter((p) => p.length > 0);
    const totalChars = Math.max(1, textStr.length);
    let currentCount = 0;

    const start = f(startPercent);
    const dur = f(durPercent);
    const eraseStart = eraseStartPercent ? f(eraseStartPercent) : undefined;
    const eraseDur = eraseDurPercent ? f(eraseDurPercent) : undefined;

    return parts.map((part) => {
      const wordStart = start + dur * (currentCount / totalChars);
      const wordDur = dur * (part.length / totalChars);

      let wordEraseStart = undefined;
      let wordEraseDur = undefined;
      if (eraseStart && eraseDur) {
        // Erase starts from the end of the sentence backwards
        const fromEndCount = totalChars - currentCount - part.length;
        wordEraseStart = eraseStart + eraseDur * (fromEndCount / totalChars);
        wordEraseDur = eraseDur * (part.length / totalChars);
      }

      currentCount += part.length;
      return {
        text: part,
        start: wordStart,
        dur: wordDur,
        eraseStart: wordEraseStart,
        eraseDur: wordEraseDur,
        isWhitespace: /^\s+$/.test(part),
      };
    });
  };

  const wordData1 = useMemo(
    () => createWordData(text, 0.075, 0.125, 0.45, 0.075),
    [text, f]
  );
  const wordData2 = useMemo(
    () => createWordData(text2, 0.55, 0.125),
    [text2, f]
  );

  // Doodle 1 Data
  const doodle1Strokes = useMemo(() => {
    const startP = 0.075;
    const durP = 0.35;
    const eStartP = 0.45;
    const eDurP = 0.075;
    const totalStrokes = doodle1StrokesBase.length;
    const timePerStroke = durP / totalStrokes;
    const eraseTimePerStroke = eDurP / totalStrokes;

    return doodle1StrokesBase.map((item, index) => {
      const d = typeof item === "string" ? item : item.d;
      const fill = typeof item === "string" ? false : item.fill;
      const start = f(startP + index * timePerStroke);
      const dur = f(timePerStroke * 1.5);

      // Erase backward (last stroke drawn is first stroke erased)
      const reverseIndex = totalStrokes - 1 - index;
      const eraseStart = f(eStartP + reverseIndex * eraseTimePerStroke);
      const eraseDur = f(eraseTimePerStroke * 1.5);

      return { d, start, dur, eraseStart, eraseDur, fill };
    });
  }, [f]);

  // Doodle 2 Data
  const doodle2Strokes = useMemo(() => {
    const startP = 0.55;
    const durP = 0.35;
    const totalStrokes = doodle2StrokesBase.length;
    const timePerStroke = durP / totalStrokes;

    return doodle2StrokesBase.map((item, index) => {
      const d = typeof item === "string" ? item : item.d;
      const fill = typeof item === "string" ? false : item.fill;
      const start = f(startP + index * timePerStroke);
      const dur = f(timePerStroke * 1.5);
      return { d, start, dur, fill };
    });
  }, [f]);

  const textFontSize = paperHeight * 0.12;

  const flattenedHighlightWords = useMemo(() => {
    return highlightWords.flatMap((hw) =>
      hw.split(/\s+/).map((w) => w.replace(/[.,!?]/g, ""))
    );
  }, [highlightWords]);

  const renderWordSequence = (
    wordData: ReturnType<typeof createWordData>
  ) => {
    return wordData.map((item, i) => {
      if (item.isWhitespace) {
        return (
          <span key={i} style={{ whiteSpace: "pre-wrap" }}>
            {item.text}
          </span>
        );
      }

      const safeDur = Math.max(0.001, item.dur);
      const clipRightDraw = interpolate(
        frame,
        [item.start, item.start + safeDur],
        [150, -50],
        { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
      );

      const safeEraseDur = Math.max(0.001, item.eraseDur || 0);
      const clipRightErase =
        item.eraseStart && item.eraseDur
          ? interpolate(
              frame,
              [item.eraseStart, item.eraseStart + safeEraseDur],
              [-50, 150],
              { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
            )
          : -50;

      const actualClipRight =
        item.eraseStart && frame >= item.eraseStart
          ? clipRightErase
          : clipRightDraw;

      const cleanWord = item.text.replace(/[.,!?]/g, "");
      const isHighlighted =
        flattenedHighlightWords.includes(item.text) ||
        flattenedHighlightWords.includes(cleanWord);

      return (
        <span
          key={i}
          style={{
            display: "inline-block",
            clipPath: `inset(-50% ${actualClipRight}% -50% -50%)`,
            whiteSpace: "pre-wrap",
            color: isHighlighted ? highlightColor : "inherit",
          }}
        >
          {item.text}
        </span>
      );
    });
  };

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor }}>
      <div
        style={{
          position: "absolute",
          width: paperWidth,
          height: paperHeight,
          left: paperLeft,
          top: paperTop,
          backgroundColor: paperColor,
          boxShadow: "0 20px 40px rgba(0,0,0,0.1), 0 5px 15px rgba(0,0,0,0.05)",
          borderRadius: "10px 15px 5px 20px / 20px 5px 15px 10px",
          transform: `scale(${paperScale}) rotate(${paperRotate}deg)`,
          transformOrigin: "center",
          overflow: "hidden",
        }}
      >
        {/* Background Lines */}
        <svg
          width="100%"
          height="100%"
          style={{ position: "absolute", top: 0, left: 0 }}
        >
          {paperLines.map((line, i) => (
            <AnimatedStroke
              key={i}
              d={line.d}
              start={line.start}
              dur={line.dur}
              frame={frame}
              color={lineColor}
              width={2}
            />
          ))}
        </svg>

        {/* Text Area */}
        <div
          style={{
            position: "absolute",
            top: lineSpacing * 1 - textFontSize * 0.15,
            width: "100%",
            textAlign: "center",
            fontFamily: caveatFamily,
            fontSize: textFontSize,
            color: textColor,
            lineHeight: `${lineSpacing}px`,
          }}
        >
          {/* Sentence 1 */}
          <div
            style={{
              position: "absolute",
              width: "100%",
              padding: `0 ${paperWidth * 0.1}px`,
              boxSizing: "border-box",
            }}
          >
            {renderWordSequence(wordData1)}
          </div>
          {/* Sentence 2 */}
          <div
            style={{
              position: "absolute",
              width: "100%",
              padding: `0 ${paperWidth * 0.1}px`,
              boxSizing: "border-box",
            }}
          >
            {renderWordSequence(wordData2)}
          </div>
        </div>

        {/* Doodle Canvas */}
        <svg
          viewBox="0 0 1000 600"
          preserveAspectRatio="xMidYMid meet"
          style={{
            position: "absolute",
            bottom: paperHeight * 0.05,
            left: paperWidth * 0.1,
            width: paperWidth * 0.8,
            height: paperHeight * 0.6,
          }}
        >
          {doodle1Strokes.map((stroke, i) => (
            <AnimatedStroke
              key={`d1-${i}`}
              d={stroke.d}
              start={stroke.start}
              dur={stroke.dur}
              eraseStart={stroke.eraseStart}
              eraseDur={stroke.eraseDur}
              frame={frame}
              color={strokeColor}
              width={strokeWidth}
              fillColor={stroke.fill ? paperColor : undefined}
            />
          ))}
          {doodle2Strokes.map((stroke, i) => (
            <AnimatedStroke
              key={`d2-${i}`}
              d={stroke.d}
              start={stroke.start}
              dur={stroke.dur}
              frame={frame}
              color={strokeColor}
              width={strokeWidth}
              fillColor={stroke.fill ? paperColor : undefined}
            />
          ))}
        </svg>
      </div>
    </AbsoluteFill>
  );
};

export default HandwritingDoodle;